object TechnicianIdentityCodec {
    const val MAX_BYTES = 16_384
    fun encode(value: TechnicianIdentity): ByteArray = JSONObject().put("format", "ServiceLoopTechnician").put("formatVersion", 1).put("technicianId", value.technicianId).put("name", value.name).toString(2).toByteArray()
    fun decode(bytes: ByteArray): TechnicianIdentity {
        require(bytes.size in 1..MAX_BYTES) { "Invalid technician identity file size" }
        val root = runCatching { JSONObject(bytes.toString(Charsets.UTF_8)) }.getOrElse { throw IllegalArgumentException("Malformed technician identity file") }
        require(root.optString("format") == "ServiceLoopTechnician" && root.optInt("formatVersion") == 1) { "Unsupported technician identity file" }
        val id = root.getString("technicianId").trim(); val name = root.getString("name").trim()
        require(id.length in 16..200 && name.length in 1..200) { "Invalid technician identity" }
        return TechnicianIdentity(id, name)
    }
}

object DispatchPackageCodec {
    const val MAX_BYTES = 1_048_576
    private const val MAX_DIRECTORY = 500
    private const val MAX_VISITS = 100
    private const val MAX_WORK = 500
    private const val MAX_STRING = 4_000

    fun encode(value: DispatchPackage): ByteArray {
        validate(value)
        fun nullable(v: Any?) = v ?: JSONObject.NULL
        fun tech(v: DispatchTechnicianSnapshot) = JSONObject().put("technicianId", v.technicianId).put("name", v.name)
        val root = JSONObject().put("format", "ServiceLoopWorkPackage").put("formatVersion", 2).put("packageId", value.packageId).put("createdAt", value.createdAt).put("senderLabel", value.senderLabel)
        root.put("customers", JSONArray(value.customers.map { JSONObject().put("reference", it.reference).put("name", it.name) }))
        root.put("sites", JSONArray(value.sites.map { JSONObject().put("reference", it.reference).put("customerReference", it.customerReference).put("name", it.name).put("address", nullable(it.address)) }))
        root.put("equipment", JSONArray(value.equipment.map { JSONObject().put("reference", it.reference).put("siteReference", it.siteReference).put("name", it.name).put("identifier", nullable(it.identifier)).put("make", nullable(it.make)).put("model", nullable(it.model)).put("serial", nullable(it.serial)) }))
        root.put("visits", JSONArray(value.visits.map { visit -> JSONObject().put("dispatchVisitId", visit.dispatchVisitId).put("generation", visit.generation).put("managerReference", nullable(visit.managerReference)).put("serviceDate", visit.serviceDate).put("appointmentLocalTime", nullable(visit.appointmentLocalTime)).put("appointmentZoneId", visit.appointmentZoneId).put("siteReference", visit.siteReference).put("instructions", nullable(visit.instructions)).put("teams", JSONArray(visit.teams.map { JSONObject().put("teamId", it.teamId).put("name", it.name).put("memberIds", JSONArray(it.memberIds)).put("leaderIds", JSONArray(it.leaderIds)) })).put("participants", JSONArray(visit.participants.map(::tech))).put("leaderTechnicianIds", JSONArray(visit.leaderTechnicianIds)).put("items", JSONArray(visit.work.map { item -> JSONObject().put("dispatchItemId", item.dispatchItemId).put("equipmentReference", item.equipmentReference).put("taskName", item.taskName).put("servicePlanReference", nullable(item.servicePlanReference)).put("dueDateSnapshot", nullable(item.dueDateSnapshot)).put("assignedTechnicians", JSONArray(item.assignedTechnicians.map(::tech))) })) }))
        return root.toString(2).toByteArray(Charsets.UTF_8).also { require(it.size <= MAX_BYTES) { "Work package exceeds 1 MiB" } }
    }

    fun decode(bytes: ByteArray): DispatchPackage {
        require(bytes.size in 1..MAX_BYTES) { "Work package exceeds 1 MiB" }
        val root = runCatching { JSONObject(bytes.toString(Charsets.UTF_8)) }.getOrElse { throw IllegalArgumentException("Malformed work package") }
        require(root.optString("format") == "ServiceLoopWorkPackage") { "Not a ServiceLoop work package" }; require(root.optInt("formatVersion", -1) == 2) { "Unsupported work package version" }
        fun JSONObject.text(name: String) = getString(name).also { require(it.isNotBlank() && it.length <= MAX_STRING) { "Invalid $name" } }
        fun JSONObject.nullable(name: String) = if (isNull(name)) null else getString(name).also { require(it.length <= MAX_STRING) { "$name is too long" } }
        fun tech(o: JSONObject) = DispatchTechnicianSnapshot(o.text("technicianId"), o.text("name"))
        fun strings(a: JSONArray) = (0 until a.length()).map { a.getString(it) }
        fun <T> array(name: String, limit: Int, read: (JSONObject) -> T): List<T> { val a=root.getJSONArray(name); require(a.length()<=limit){"Too many $name"}; return (0 until a.length()).map{read(a.getJSONObject(it))} }
        val customers=array("customers",MAX_DIRECTORY){DispatchCustomer(it.text("reference"),it.text("name"))}; val sites=array("sites",MAX_DIRECTORY){DispatchSite(it.text("reference"),it.text("customerReference"),it.text("name"),it.nullable("address"))}; val equipment=array("equipment",MAX_DIRECTORY){DispatchEquipment(it.text("reference"),it.text("siteReference"),it.text("name"),it.nullable("identifier"),it.nullable("make"),it.nullable("model"),it.nullable("serial"))}
        val visits=array("visits",MAX_VISITS){v-> val teams=v.getJSONArray("teams");val participants=v.getJSONArray("participants");val items=v.getJSONArray("items");require(items.length() in 1..MAX_WORK){"Invalid item count"};DispatchVisit(v.text("dispatchVisitId"),v.getInt("generation"),v.nullable("managerReference"),v.text("serviceDate"),v.nullable("appointmentLocalTime"),v.text("appointmentZoneId"),v.text("siteReference"),v.nullable("instructions"),(0 until teams.length()).map{teams.getJSONObject(it).let{t->DispatchTeamSnapshot(t.text("teamId"),t.text("name"),strings(t.getJSONArray("memberIds")),strings(t.getJSONArray("leaderIds")))}},(0 until participants.length()).map{tech(participants.getJSONObject(it))},strings(v.getJSONArray("leaderTechnicianIds")),(0 until items.length()).map{items.getJSONObject(it).let{item->val assigned=item.getJSONArray("assignedTechnicians");DispatchWork(item.text("dispatchItemId"),item.text("equipmentReference"),item.text("taskName"),item.nullable("servicePlanReference"),item.nullable("dueDateSnapshot"),(0 until assigned.length()).map{a->tech(assigned.getJSONObject(a))})}})}
        return DispatchPackage(root.text("packageId"),root.text("createdAt"),root.text("senderLabel"),customers,sites,equipment,visits).also(::validate)
    }
    fun materialHash(value: DispatchVisit): String {
        val canonical=value.copy(
            teams=value.teams.sortedBy{it.teamId}.map{it.copy(memberIds=it.memberIds.sorted(),leaderIds=it.leaderIds.sorted())},
            participants=value.participants.sortedBy{it.technicianId},leaderTechnicianIds=value.leaderTechnicianIds.sorted(),
            work=value.work.sortedBy{it.dispatchItemId}.map{it.copy(assignedTechnicians=it.assignedTechnicians.sortedBy{x->x.technicianId})},
        ).toString()
        return sha256(canonical)
    }
    private fun validate(value: DispatchPackage) {
        require(value.packageId.isNotBlank()&&value.senderLabel.isNotBlank());Instant.parse(value.createdAt);require(value.visits.isNotEmpty()&&value.visits.size<=MAX_VISITS);require(value.visits.map{it.dispatchVisitId}.distinct().size==value.visits.size){"Duplicate dispatch visit ID"};require(value.customers.size<=MAX_DIRECTORY&&value.sites.size<=MAX_DIRECTORY&&value.equipment.size<=MAX_DIRECTORY);require(value.customers.map{it.reference}.distinct().size==value.customers.size);require(value.sites.map{it.reference}.distinct().size==value.sites.size);require(value.equipment.map{it.reference}.distinct().size==value.equipment.size)
        val customerRefs=value.customers.map{it.reference}.toSet();val siteRefs=value.sites.map{it.reference}.toSet();val equipmentRefs=value.equipment.map{it.reference}.toSet();require(value.sites.all{it.customerReference in customerRefs}&&value.equipment.all{it.siteReference in siteRefs}){"Broken directory reference"}
        value.visits.forEach{v->require(v.generation>=1);LocalDate.parse(v.serviceDate);ZoneId.of(v.appointmentZoneId);v.appointmentLocalTime?.let(LocalTime::parse);require(v.siteReference in siteRefs&&v.work.isNotEmpty()&&v.work.size<=MAX_WORK);require(v.work.map{it.dispatchItemId}.distinct().size==v.work.size){"Duplicate dispatch item ID"};val participants=v.participants.map{it.technicianId};require(participants.distinct().size==participants.size&&participants.isNotEmpty());require(v.leaderTechnicianIds.all{it in participants});require(v.teams.flatMap{it.memberIds}.toSet()==participants.toSet());require(v.teams.flatMap{it.leaderIds}.toSet()==v.leaderTechnicianIds.toSet());v.work.forEach{i->require(i.equipmentReference in equipmentRefs);i.dueDateSnapshot?.let(LocalDate::parse);require(i.assignedTechnicians.map{it.technicianId}.distinct().size==i.assignedTechnicians.size);require(i.assignedTechnicians.all{it.technicianId in participants})}}
    }
}

enum class DispatchClassification { EXISTING_UNCHANGED, NEW, CONFLICT, POSSIBLE_DUPLICATE }
enum class DispatchVisitClassification { NEW_VISIT, UPDATE, ALREADY_CURRENT, OLDER_GENERATION, CONFLICT, LOCAL_CONFLICT, UPDATE_BLOCKED, NOT_ASSIGNED }
data class DispatchPreviewLine(val reference:String,val classification:DispatchClassification,val detail:String)
data class DispatchItemPreview(val dispatchItemId:String,val taskName:String,val localRole:String,val change:String)
data class DispatchVisitPreview(val dispatchVisitId:String,val generation:Int,val classification:DispatchVisitClassification,val reasons:List<String>,val localVisitId:String?=null,val items:List<DispatchItemPreview> = emptyList())
data class DispatchPreview(val value:DispatchPackage,val identity:TechnicianIdentity,val directory:List<DispatchPreviewLine>,val visits:List<DispatchVisitPreview>){val canImport get()=directory.none{it.classification in setOf(DispatchClassification.CONFLICT,DispatchClassification.POSSIBLE_DUPLICATE)}&&visits.none{it.classification in setOf(DispatchVisitClassification.CONFLICT,DispatchVisitClassification.LOCAL_CONFLICT)}&&visits.any{it.classification in setOf(DispatchVisitClassification.NEW_VISIT,DispatchVisitClassification.UPDATE)}}
data class DispatchImportResult(val createdVisitIds:List<String>,val updatedVisitIds:List<String>,val unchangedVisitIds:List<String>)
data class DispatchTeamDetail(val team:DispatchTeamEntity,val members:List<Pair<DispatchTechnicianEntity,Boolean>>)

class DispatchPackageService(private val database:ServiceLoopDatabase,private val fileRoot:File?=null){
    private val dao=database.serviceLoopDao();private val dispatch=database.dispatchDao()
    private fun normal(v:String?)=v.orEmpty().trim().lowercase().replace(Regex("\\s+")," ");private fun stable(vararg p:String)=UUID.nameUUIDFromBytes(p.joinToString("|").toByteArray()).toString()
    private fun techJson(v:List<DispatchTechnicianSnapshot>)=JSONArray(v.map{JSONObject().put("technicianId",it.technicianId).put("name",it.name)}).toString();private fun teamsJson(v:List<DispatchTeamSnapshot>)=JSONArray(v.map{JSONObject().put("teamId",it.teamId).put("name",it.name).put("memberIds",JSONArray(it.memberIds)).put("leaderIds",JSONArray(it.leaderIds))}).toString();private fun idsJson(v:List<String>)=JSONArray(v).toString()
    suspend fun identity():TechnicianIdentity{dispatch.technicianIdentity()?.let{return TechnicianIdentity(it.technicianId,it.displayName)};val now=System.currentTimeMillis();val name=dao.businessProfile()?.technicianName?.trim().takeUnless{it.isNullOrEmpty()}?:"Technician";runCatching{dispatch.insertTechnicianIdentity(TechnicianIdentityEntity(technicianId=UUID.randomUUID().toString(),displayName=name,createdAtEpochMillis=now,modifiedAtEpochMillis=now))};return dispatch.technicianIdentity()!!.let{TechnicianIdentity(it.technicianId,it.displayName)}}
    suspend fun renameIdentity(name:String):TechnicianIdentity{require(name.trim().isNotEmpty());val c=dispatch.technicianIdentity()?:run{identity();dispatch.technicianIdentity()!!};dispatch.updateTechnicianIdentity(c.copy(displayName=name.trim(),modifiedAtEpochMillis=System.currentTimeMillis()));return identity()}
    suspend fun importTechnician(v:TechnicianIdentity,confirmRename:Boolean=false){val now=System.currentTimeMillis();val p=dispatch.technician(v.technicianId);when{p==null->dispatch.insertTechnician(DispatchTechnicianEntity(v.technicianId,v.name,now,now));p.displayName==v.name->Unit;confirmRename->dispatch.updateTechnician(p.copy(displayName=v.name,modifiedAtEpochMillis=now));else->error("Technician ID already exists with a different name; confirm the name update")}}
    suspend fun technicians()=dispatch.technicians();suspend fun createTeam(name:String):String{require(name.trim().isNotEmpty());val id=UUID.randomUUID().toString();val n=System.currentTimeMillis();dispatch.insertTeam(DispatchTeamEntity(id,name.trim(),n,n));return id}
    suspend fun renameTeam(id:String,name:String){val team=dispatch.team(id)?:error("Team missing");require(name.trim().isNotEmpty());dispatch.updateTeam(team.copy(name=name.trim(),modifiedAtEpochMillis=System.currentTimeMillis()))}
    suspend fun setTeamMember(teamId:String,techId:String,present:Boolean,isLeader:Boolean=false){dispatch.team(teamId)?:error("Team missing");dispatch.technician(techId)?:error("Technician missing");val c=dispatch.teamMembers(teamId).find{it.technicianId==techId};if(!present&&c!=null)dispatch.removeTeamMember(teamId,techId)else if(present&&c==null)dispatch.insertTeamMember(DispatchTeamMemberEntity(teamId,techId,isLeader))else if(present&&c!!.isLeader!=isLeader)dispatch.updateTeamMember(c.copy(isLeader=isLeader))}
    suspend fun teams():List<DispatchTeamDetail>{val t=dispatch.technicians().associateBy{it.technicianId};return dispatch.teams().map{x->DispatchTeamDetail(x,dispatch.teamMembers(x.id).mapNotNull{m->t[m.technicianId]?.let{it to m.isLeader}})}}
    suspend fun createOutboxVisit(manager:String?,siteId:String,date:String,time:String?,zone:String,instructions:String?,teamIds:List<String>):String=database.withTransaction{LocalDate.parse(date);time?.let(LocalTime::parse);ZoneId.of(zone);require(teamIds.isNotEmpty());dao.site(siteId)?:error("Site missing");val id=UUID.randomUUID().toString();val n=System.currentTimeMillis();dispatch.insertOutboxVisit(DispatchOutboxVisitEntity(id,manager?.trim()?.takeIf{it.isNotEmpty()},siteId,date,time,zone,instructions?.trim()?.takeIf{it.isNotEmpty()},null,null,null,n,n));dispatch.insertOutboxVisitTeams(teamIds.distinct().map{DispatchOutboxVisitTeamEntity(id,it)});id}
    suspend fun addOutboxItem(visitId:String,equipmentId:String,task:String,plan:String?,due:String?,assigned:List<String>):String=database.withTransaction{require(task.trim().isNotEmpty());val v=dispatch.outboxVisit(visitId)?:error("Outbox visit missing");val e=dao.equipment(equipmentId)?:error("Equipment missing");require(e.siteId==v.siteId);val participants=expand(visitId).first.map{it.technicianId}.toSet();require(assigned.all{it in participants}){"Assignee is outside selected teams"};val id=UUID.randomUUID().toString();dispatch.insertOutboxItem(DispatchOutboxItemEntity(id,visitId,dispatch.outboxItems(visitId).size,equipmentId,task.trim(),plan,due));dispatch.insertOutboxItemAssignees(assigned.distinct().map{DispatchOutboxItemAssigneeEntity(id,it)});id}
    suspend fun outboxVisits()=dispatch.outboxVisits();private suspend fun expand(id:String):Pair<List<DispatchTechnicianEntity>,Set<String>>{val teams=dispatch.outboxVisitTeams(id).map{it.teamId}.toSet();val members=dispatch.allTeamMembers().filter{it.teamId in teams};val tech=dispatch.technicians().associateBy{it.technicianId};return members.mapNotNull{tech[it.technicianId]}.distinctBy{it.technicianId} to members.filter{it.isLeader}.map{it.technicianId}.toSet()}
    suspend fun rescheduleOutboxVisit(id:String,date:String,time:String?,zone:String){LocalDate.parse(date);time?.let(LocalTime::parse);ZoneId.of(zone);val value=dispatch.outboxVisit(id)?:error("Outbox visit missing");dispatch.updateOutboxVisit(value.copy(serviceDate=date,appointmentLocalTime=time,appointmentZoneId=zone,modifiedAtEpochMillis=System.currentTimeMillis()))}
    private suspend fun compose(o:DispatchOutboxVisitEntity,g:Int):DispatchVisit{val s=dao.site(o.siteId)?:error("Site missing");val teamIds=dispatch.outboxVisitTeams(o.dispatchVisitId).map{it.teamId};val allTeams=dispatch.teams().associateBy{it.id};val members=dispatch.allTeamMembers();val tech=dispatch.technicians().associateBy{it.technicianId};val teams=teamIds.map{id->val t=allTeams[id]?:error("Team missing");val m=members.filter{it.teamId==id};DispatchTeamSnapshot(id,t.name,m.map{it.technicianId}.sorted(),m.filter{it.isLeader}.map{it.technicianId}.sorted())};val participants=teams.flatMap{it.memberIds}.distinct().sorted().map{tech[it]?.let{x->DispatchTechnicianSnapshot(x.technicianId,x.displayName)}?:error("Technician missing")};val items=dispatch.outboxItems(o.dispatchVisitId).map{i->val e=dao.equipment(i.equipmentId)?:error("Equipment missing");val assigned=dispatch.outboxItemAssignees(i.dispatchItemId).map{it.technicianId}.sorted().map{tech[it]?.let{x->DispatchTechnicianSnapshot(x.technicianId,x.displayName)}?:error("Technician missing")};DispatchWork(i.dispatchItemId,e.reference,i.taskName,i.servicePlanReference,i.dueDateSnapshot,assigned)};require(items.isNotEmpty());return DispatchVisit(o.dispatchVisitId,g,o.managerReference,o.serviceDate,o.appointmentLocalTime,o.appointmentZoneId,s.reference,o.instructions,teams,participants,teams.flatMap{it.leaderIds}.distinct().sorted(),items)}
    suspend fun exportPackage(ids:List<String>,sender:String):DispatchPackage=database.withTransaction{require(sender.trim().isNotEmpty());val now=System.currentTimeMillis();val visits=ids.distinct().map{id->val o=dispatch.outboxVisit(id)?:error("Outbox visit missing");val candidate=compose(o,o.lastExportedGeneration?:1);val h=DispatchPackageCodec.materialHash(candidate);val g=when{o.lastExportedGeneration==null->1;h==o.lastExportedMaterialHash->o.lastExportedGeneration;else->o.lastExportedGeneration+1};val v=if(g==candidate.generation)candidate else compose(o,g);dispatch.updateOutboxVisit(o.copy(lastExportedGeneration=g,lastExportedMaterialHash=DispatchPackageCodec.materialHash(v),lastExportedAtEpochMillis=now));v};val sr=visits.map{it.siteReference}.toSet();val sites=dao.allSites().filter{it.reference in sr};val customers=dao.allCustomers().filter{c->sites.any{it.customerId==c.id}};val er=visits.flatMap{it.work}.map{it.equipmentReference}.toSet();val equipment=dao.allEquipment().filter{it.reference in er};DispatchPackage(UUID.randomUUID().toString(),Instant.ofEpochMilli(now).toString(),sender.trim(),customers.map{DispatchCustomer(it.reference,it.name)},sites.map{s->DispatchSite(s.reference,customers.single{it.id==s.customerId}.reference,s.name,s.address)},equipment.map{e->DispatchEquipment(e.reference,sites.single{it.id==e.siteId}.reference,e.name,e.technicianIdentifier,e.make,e.model,e.serialNumber)},visits)}
    private fun applicable(v:DispatchVisit,id:TechnicianIdentity):List<Pair<DispatchWork,String>>{val leader=id.technicianId in v.leaderTechnicianIds;return v.work.mapNotNull{i->val assigned=i.assignedTechnicians.isEmpty()||i.assignedTechnicians.any{it.technicianId==id.technicianId};when{assigned->i to "ASSIGNED";leader->i to "LEADER_VISIBLE";else->null}}};private fun scheduled(v:DispatchVisit)=v.appointmentLocalTime?.let{LocalDate.parse(v.serviceDate).atTime(LocalTime.parse(it)).atZone(ZoneId.of(v.appointmentZoneId)).toInstant().toEpochMilli()}
    private suspend fun fingerprint(localId:String):String{val v=dao.visit(localId)?:return "missing";val b=dispatch.visitBindingForLocalVisit(localId)?:return "missing";val items=dispatch.itemBindings(b.dispatchVisitId).mapNotNull{x->x.localWorkItemId?.let{dao.workItem(it)}?.let{w->"${x.dispatchItemId}|${w.equipmentReferenceSnapshot}|${w.serviceNameSnapshot}"}}.sorted();return sha256(listOf(v.actualServiceDate,v.scheduledAtEpochMillis,v.appointmentZoneId,items.joinToString(";")).joinToString("|"))};private fun incoming(v:DispatchVisit,r:List<Pair<DispatchWork,String>>)=sha256(listOf(v.serviceDate,scheduled(v),v.appointmentZoneId,r.map{"${it.first.dispatchItemId}|${it.first.equipmentReference}|${it.first.taskName}"}.sorted().joinToString(";")).joinToString("|"))
    suspend fun preview(value:DispatchPackage):DispatchPreview{val id=identity();val customers=dao.allCustomers();val sites=dao.allSites();val equipment=dao.allEquipment();val relevantVisits=value.visits.filter{id.technicianId in it.participants.map{x->x.technicianId}&&applicable(it,id).isNotEmpty()};val neededSites=relevantVisits.map{it.siteReference}.toSet();val neededEquipment=relevantVisits.flatMap{it.work}.map{it.equipmentReference}.toSet();val neededCustomers=value.sites.filter{it.reference in neededSites}.map{it.customerReference}.toSet();val directory=buildList{value.customers.filter{it.reference in neededCustomers}.forEach{x->val exact=customers.find{it.reference==x.reference};add(DispatchPreviewLine(x.reference,when{exact!=null&&normal(exact.name)==normal(x.name)->DispatchClassification.EXISTING_UNCHANGED;exact!=null->DispatchClassification.CONFLICT;customers.any{normal(it.name)==normal(x.name)}->DispatchClassification.POSSIBLE_DUPLICATE;else->DispatchClassification.NEW},"Customer · ${x.name}"))};value.sites.filter{it.reference in neededSites}.forEach{x->val exact=sites.find{it.reference==x.reference};val parent=exact?.let{s->customers.find{it.id==s.customerId}?.reference};add(DispatchPreviewLine(x.reference,when{exact!=null&&parent==x.customerReference&&normal(exact.name)==normal(x.name)&&normal(exact.address)==normal(x.address)->DispatchClassification.EXISTING_UNCHANGED;exact!=null->DispatchClassification.CONFLICT;sites.any{normal(it.name)==normal(x.name)&&normal(it.address)==normal(x.address)}->DispatchClassification.POSSIBLE_DUPLICATE;else->DispatchClassification.NEW},"Site · ${x.name}"))};value.equipment.filter{it.reference in neededEquipment}.forEach{x->val exact=equipment.find{it.reference==x.reference};val parent=exact?.let{e->sites.find{it.id==e.siteId}?.reference};add(DispatchPreviewLine(x.reference,when{exact!=null&&parent==x.siteReference&&normal(exact.name)==normal(x.name)&&normal(exact.serialNumber)==normal(x.serial)->DispatchClassification.EXISTING_UNCHANGED;exact!=null->DispatchClassification.CONFLICT;equipment.any{normal(it.serialNumber)==normal(x.serial)&&normal(x.serial).isNotBlank()}->DispatchClassification.POSSIBLE_DUPLICATE;else->DispatchClassification.NEW},"Equipment · ${x.name}"))}};val visits=value.visits.map{v->val r=applicable(v,id);val participant=id.technicianId in v.participants.map{it.technicianId};val b=dispatch.visitBinding(v.dispatchVisitId);val h=DispatchPackageCodec.materialHash(v);val c=when{!participant||r.isEmpty()->DispatchVisitClassification.NOT_ASSIGNED;b==null->DispatchVisitClassification.NEW_VISIT;v.generation==b.appliedGeneration&&h==b.appliedMaterialHash->DispatchVisitClassification.ALREADY_CURRENT;v.generation==b.appliedGeneration->DispatchVisitClassification.CONFLICT;v.generation<b.appliedGeneration->DispatchVisitClassification.OLDER_GENERATION;dao.visit(b.localVisitId)?.state!="BOOKED"->DispatchVisitClassification.UPDATE_BLOCKED;fingerprint(b.localVisitId)!=b.controlledFingerprint->DispatchVisitClassification.LOCAL_CONFLICT;else->DispatchVisitClassification.UPDATE};val reasons=when(c){DispatchVisitClassification.NOT_ASSIGNED->listOf("No work in this Visit is assigned to this Technician identity");DispatchVisitClassification.CONFLICT->listOf("Same generation has different content");DispatchVisitClassification.LOCAL_CONFLICT->listOf("Local changes conflict with dispatch generation ${v.generation}");DispatchVisitClassification.UPDATE_BLOCKED->listOf("Newer generation available, but this local Visit has already started");DispatchVisitClassification.OLDER_GENERATION->listOf("Older generation will not roll local work backward");else->emptyList()};DispatchVisitPreview(v.dispatchVisitId,v.generation,c,reasons,b?.localVisitId,r.map{DispatchItemPreview(it.first.dispatchItemId,it.first.taskName,it.second,"CURRENT_OR_CHANGED")})};return DispatchPreview(value,id,directory,visits)}
    suspend fun import(p:DispatchPreview):DispatchImportResult{require(p.canImport);val created=mutableListOf<String>();val updated=mutableListOf<String>();val unchanged=mutableListOf<String>();database.withTransaction{val fresh=this@DispatchPackageService.preview(p.value);require(fresh.canImport);val actionableIds=fresh.visits.filter{it.classification in setOf(DispatchVisitClassification.NEW_VISIT,DispatchVisitClassification.UPDATE)}.map{it.dispatchVisitId}.toSet();val actionable=p.value.visits.filter{it.dispatchVisitId in actionableIds};val neededSites=actionable.map{it.siteReference}.toSet();val neededEquipment=actionable.flatMap{it.work}.map{it.equipmentReference}.toSet();val neededCustomers=p.value.sites.filter{it.reference in neededSites}.map{it.customerReference}.toSet();val customers=dao.allCustomers().associateBy{it.reference}.toMutableMap();p.value.customers.filter{it.reference in neededCustomers}.forEach{x->if(x.reference !in customers){CustomerEntity(stable("dispatch-customer",x.reference),x.reference,x.name).also{dao.insertCustomers(listOf(it));customers[x.reference]=it}}};val sites=dao.allSites().associateBy{it.reference}.toMutableMap();p.value.sites.filter{it.reference in neededSites}.forEach{x->if(x.reference !in sites){val c=customers[x.customerReference]?:error("Missing customer");SiteEntity(stable("dispatch-site",x.reference),c.id,x.reference,x.name,x.address,null).also{dao.insertSites(listOf(it));sites[x.reference]=it}}};val equipment=dao.allEquipment().associateBy{it.reference}.toMutableMap();p.value.equipment.filter{it.reference in neededEquipment}.forEach{x->if(x.reference !in equipment){val s=sites[x.siteReference]?:error("Missing site");EquipmentEntity(stable("dispatch-equipment",x.reference),s.id,x.reference,x.identifier,x.name,x.make,x.model,x.serial,null).also{dao.insertEquipment(listOf(it));equipment[x.reference]=it}}};val now=System.currentTimeMillis();fresh.visits.forEach{pv->val v=p.value.visits.single{it.dispatchVisitId==pv.dispatchVisitId};when(pv.classification){DispatchVisitClassification.NEW_VISIT->{val r=applicable(v,fresh.identity);val s=sites[v.siteReference]?:error("Missing site");val c=customers.values.single{it.id==s.customerId};val local=stable("dispatch-visit",v.dispatchVisitId);dao.insertVisits(listOf(WorkingVisitEntity(local,"D-${v.dispatchVisitId.take(12)}",c.id,s.id,v.serviceDate,c.name,s.name,s.address,"BOOKED",now,c.reference,s.reference,scheduledAtEpochMillis=scheduled(v),appointmentZoneId=v.appointmentZoneId)));dispatch.insertVisitBinding(DispatchVisitBindingEntity(v.dispatchVisitId,local,v.generation,p.value.packageId,p.value.senderLabel,v.managerReference,techJson(v.participants),idsJson(v.leaderTechnicianIds),teamsJson(v.teams),DispatchPackageCodec.materialHash(v),incoming(v,r),now,now));r.forEach{(i,role)->insertItem(v,i,role,local,equipment)};created+=local};DispatchVisitClassification.UPDATE->{applyUpdate(v,p.value,pv.localVisitId!!,equipment,now,fresh.identity);updated+=pv.localVisitId};else->pv.localVisitId?.let{unchanged+=it}}}};return DispatchImportResult(created,updated,unchanged)}
    private suspend fun insertItem(v:DispatchVisit,i:DispatchWork,role:String,local:String,equipment:Map<String,EquipmentEntity>){val e=equipment[i.equipmentReference]?:error("Equipment missing");val work=stable("dispatch-work",v.dispatchVisitId,i.dispatchItemId);dao.insertWorkItems(listOf(WorkItemEntity(work,local,e.id,null,null,null,e.name,e.reference,i.taskName,null,null,null,null,false,null,false,equipmentIdentifierSnapshot=e.technicianIdentifier,equipmentMakeSnapshot=e.make,equipmentModelSnapshot=e.model,equipmentSerialSnapshot=e.serialNumber)));dao.insertPublicDrafts(listOf(WorkItemPublicDraftEntity(work,"")));dao.insertPrivateDrafts(listOf(WorkItemPrivateDraftEntity(work,v.instructions.orEmpty())));dispatch.insertItemBindings(listOf(DispatchItemBindingEntity(v.dispatchVisitId,i.dispatchItemId,work,i.equipmentReference,i.taskName,i.servicePlanReference,i.dueDateSnapshot,techJson(i.assignedTechnicians),if(i.assignedTechnicians.isEmpty())"EVERYONE" else "EXPLICIT",role,if(role=="LEADER_VISIBLE")"LEADER_OBSERVE" else "PENDING")))}
    private suspend fun applyUpdate(v:DispatchVisit,p:DispatchPackage,local:String,equipment:Map<String,EquipmentEntity>,now:Long,id:TechnicianIdentity){val r=applicable(v,id);check(dispatch.updateBookedDispatchVisit(local,v.serviceDate,scheduled(v),v.appointmentZoneId,now)==1);val existing=dispatch.itemBindings(v.dispatchVisitId).associateBy{it.dispatchItemId};existing.values.filter{it.dispatchItemId !in r.map{x->x.first.dispatchItemId}.toSet()}.forEach{x->x.localWorkItemId?.let{dispatch.deleteWorkItem(it)};dispatch.deleteItemBinding(v.dispatchVisitId,x.dispatchItemId)};r.forEach{(i,role)->val old=existing[i.dispatchItemId];if(old==null)insertItem(v,i,role,local,equipment)else{val e=equipment[i.equipmentReference]?:error("Equipment missing");check(dispatch.updateBookedDispatchWork(old.localWorkItemId!!,e.id,e.name,e.reference,e.technicianIdentifier,e.make,e.model,e.serialNumber,i.taskName)==1);dispatch.updateItemBinding(old.copy(equipmentReferenceSnapshot=i.equipmentReference,taskNameSnapshot=i.taskName,servicePlanReferenceSnapshot=i.servicePlanReference,dueDateSnapshot=i.dueDateSnapshot,assignedTechniciansJson=techJson(i.assignedTechnicians),assignmentMeaning=if(i.assignedTechnicians.isEmpty())"EVERYONE" else "EXPLICIT",localRole=role,documentationDisposition=if(role=="LEADER_VISIBLE")"LEADER_OBSERVE" else "PENDING",deferredToTechnicianId=null,deferredToName=null))}};val b=dispatch.visitBinding(v.dispatchVisitId)!!;dispatch.updateVisitBinding(b.copy(appliedGeneration=v.generation,packageId=p.packageId,senderLabel=p.senderLabel,managerReference=v.managerReference,participantSnapshotJson=techJson(v.participants),leaderIdsJson=idsJson(v.leaderTechnicianIds),teamSnapshotJson=teamsJson(v.teams),appliedMaterialHash=DispatchPackageCodec.materialHash(v),controlledFingerprint=incoming(v,r),updatedAtEpochMillis=now))}
    suspend fun dispatchDetail(local:String)=dispatch.visitBindingForLocalVisit(local)?.let{it to dispatch.itemBindings(it.dispatchVisitId)}
    suspend fun documentLocally(local:String,itemId:String):String=database.withTransaction{val visit=dao.visit(local)?:error("Visit missing");require(visit.state=="WORKING");val vb=dispatch.visitBindingForLocalVisit(local)?:error("Not dispatched");val item=dispatch.itemBinding(vb.dispatchVisitId,itemId)?:error("Item missing");val work=item.localWorkItemId?:error("Work missing");val plan=dao.allPlans().find{it.reference==item.servicePlanReferenceSnapshot};val eq=dao.workItem(work)?.let{dao.equipment(it.equipmentId)};val obligation=plan?.currentObligationId?.let{dao.obligation(it)};val safe=plan!=null&&eq!=null&&plan.equipmentId==eq.id&&plan.state=="ACTIVE"&&obligation!=null&&obligation.consumedAtEpochMillis==null&&dao.claimForObligation(obligation.id)==null&&(item.dueDateSnapshot==null||item.dueDateSnapshot==obligation.dueDate);if(safe){check(dispatch.linkDispatchWork(work,plan!!.id,obligation!!.id,plan.reference,obligation.dueDate,plan.intervalCount,plan.intervalUnit)==1);dao.insertVisitClaim(VisitClaimEntity(obligation.id,local,System.currentTimeMillis()))};dispatch.updateItemBinding(item.copy(documentationDisposition="DOCUMENT_LOCAL",deferredToTechnicianId=null,deferredToName=null));if(safe)"Linked to current local obligation" else "Documenting as one-off"}
    suspend fun handoff(local:String,itemId:String,target:DispatchTechnicianSnapshot,discard:Boolean=false){val v=dao.visit(local)?:error("Visit missing");require(v.state=="WORKING");val vb=dispatch.visitBindingForLocalVisit(local)?:error("Not dispatched");val item=dispatch.itemBinding(vb.dispatchVisitId,itemId)?:error("Item missing");val eligible=(if(item.assignmentMeaning=="EVERYONE")parseTech(vb.participantSnapshotJson)else parseTech(item.assignedTechniciansJson)).map{it.technicianId}.toSet()+parseIds(vb.leaderIdsJson);require(target.technicianId in eligible&&target.technicianId!=identity().technicianId);val work=item.localWorkItemId!!;val w=dao.workItem(work)!!;val substantive=dao.publicDraft(work)?.workPerformed?.isNotBlank()==true||w.outcome!=null||dispatch.responseCount(work)>0||dispatch.partCount(work)>0||dispatch.attachmentCount(work)>0;require(!substantive||discard){"Local documentation exists; explicitly discard it before handoff"};if(discard){dispatch.workAttachments(work).forEach{a->fileRoot?.let{File(it,a.storedRelativePath).delete()}};database.withTransaction{dispatch.deleteResponses(work);dispatch.deleteParts(work);dispatch.deleteWorkAttachments(work);dispatch.clearPublicDraft(work);dispatch.clearPrivateDraft(work);w.capturedObligationId?.let{dao.releaseVisitClaim(it)};dispatch.unlinkDispatchWork(work);dispatch.updateItemBinding(item.copy(documentationDisposition="DEFERRED",deferredToTechnicianId=target.technicianId,deferredToName=target.name))}}else dispatch.updateItemBinding(item.copy(documentationDisposition="DEFERRED",deferredToTechnicianId=target.technicianId,deferredToName=target.name))}
    suspend fun undoHandoff(local:String,itemId:String){require(dao.visit(local)?.state=="WORKING");val vb=dispatch.visitBindingForLocalVisit(local)!!;val item=dispatch.itemBinding(vb.dispatchVisitId,itemId)!!;dispatch.updateItemBinding(item.copy(documentationDisposition=if(item.localRole=="LEADER_VISIBLE")"LEADER_OBSERVE" else "PENDING",deferredToTechnicianId=null,deferredToName=null))}
    suspend fun finishInvolvement(local:String)=database.withTransaction{require(dao.visit(local)?.state=="WORKING");val vb=dispatch.visitBindingForLocalVisit(local)!!;val items=dispatch.itemBindings(vb.dispatchVisitId);require(items.none{it.documentationDisposition=="DOCUMENT_LOCAL"}&&items.filter{it.localRole=="ASSIGNED"}.all{it.documentationDisposition=="DEFERRED"});check(dispatch.completeParticipation(local,System.currentTimeMillis())==1);dao.releaseVisitClaims(local)}
    fun parseTech(json:String):List<DispatchTechnicianSnapshot>{val a=JSONArray(json);return(0 until a.length()).map{a.getJSONObject(it).let{o->DispatchTechnicianSnapshot(o.getString("technicianId"),o.getString("name"))}}};fun parseIds(json:String):List<String>{val a=JSONArray(json);return(0 until a.length()).map{a.getString(it)}}
}
internal fun sha256(v:String)=MessageDigest.getInstance("SHA-256").digest(v.toByteArray()).joinToString(""){"%02x".format(it)}
